function isSpaceLikeChar(char) {
  return char === ' ' || char === '\t' || char === '\n' || char === '\r' || char === '\f' || char === '\v';
}

export function normalizeNewlines(value) {
  let result = '';

  for (let index = 0; index < value.length; index += 1) {
    const char = value[index];

    if (char === '\r') {
      if (index + 1 < value.length && value[index + 1] === '\n') {
        index += 1;
      }
      result += '\n';
      continue;
    }

    result += char;
  }

  return result;
}

export function splitLines(value) {
  const lines = [];
  let start = 0;

  for (let index = 0; index < value.length; index += 1) {
    if (value[index] === '\n') {
      lines.push(value.slice(start, index));
      start = index + 1;
    }
  }

  lines.push(value.slice(start));
  return lines;
}

export function isBlank(value) {
  for (let index = 0; index < value.length; index += 1) {
    const char = value[index];
    if (char !== ' ' && char !== '\t') {
      return false;
    }
  }

  return true;
}

export function trimAsciiWhitespace(value) {
  let start = 0;
  let end = value.length;

  while (start < end && isSpaceLikeChar(value[start])) {
    start += 1;
  }

  while (end > start && isSpaceLikeChar(value[end - 1])) {
    end -= 1;
  }

  return value.slice(start, end);
}

export function trimLeadingSpaces(value) {
  let start = 0;

  while (start < value.length && (value[start] === ' ' || value[start] === '\t')) {
    start += 1;
  }

  return value.slice(start);
}

export function countLeadingColumns(value) {
  let columns = 0;

  for (let index = 0; index < value.length; index += 1) {
    const char = value[index];
    if (char === ' ') {
      columns += 1;
      continue;
    }

    if (char === '\t') {
      columns += 4;
      continue;
    }

    break;
  }

  return columns;
}

export function stripIndent(value, width) {
  let columns = 0;
  let index = 0;

  while (index < value.length && columns < width) {
    const char = value[index];

    if (char === ' ') {
      columns += 1;
      index += 1;
      continue;
    }

    if (char === '\t') {
      columns += 4;
      index += 1;
      continue;
    }

    break;
  }

  return value.slice(index);
}

export function getOptionalIndentInfo(value, maxColumns = 3) {
  let columns = 0;
  let index = 0;

  while (index < value.length) {
    const char = value[index];
    if (char !== ' ' && char !== '\t') {
      break;
    }

    columns += char === '\t' ? 4 : 1;
    if (columns > maxColumns) {
      return null;
    }

    index += 1;
  }

  return { columns, index };
}

export function isAsciiDigit(char) {
  return char >= '0' && char <= '9';
}

export function isAsciiLetter(char) {
  return (char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z');
}

export function isWordLikeChar(char) {
  if (!char) {
    return false;
  }

  if (isAsciiLetter(char) || isAsciiDigit(char)) {
    return true;
  }

  return char.charCodeAt(0) > 127;
}

export function basename(value) {
  if (!value) {
    return '';
  }

  let start = 0;

  for (let index = 0; index < value.length; index += 1) {
    const char = value[index];
    if (char === '/' || char === '\\') {
      start = index + 1;
    }
  }

  return value.slice(start);
