      blocks.push(`<blockquote>\n${innerHtml}\n</blockquote>`);
      continue;
    }

    const listMarker = detectListMarker(line);
    if (listMarker) {
      const tagName = listMarker.type === 'ol' ? 'ol' : 'ul';
      const itemIndentLimit = listMarker.indent + 3;
      const items = [];

      while (index < lines.length) {
