            const nextNonBlank = findNextNonBlank(lines, index + 1, lines.length);
            if (nextNonBlank >= lines.length) {
              index = lines.length;
              break;
            }

            const nextMarker = detectListMarker(lines[nextNonBlank]);
            if (nextMarker && nextMarker.type === listMarker.type && nextMarker.indent <= itemIndentLimit) {
              break;
            }

            const nextIndent = countLeadingColumns(lines[nextNonBlank]);
            if (nextIndent >= baseIndent) {
              tailLines.push('');
              index = nextNonBlank;
              continue;
            }

            break;
          }

          const siblingMarker = detectListMarker(currentLine);
          if (siblingMarker && siblingMarker.type === listMarker.type && siblingMarker.indent <= itemIndentLimit) {
            break;
          }

          const indent = countLeadingColumns(currentLine);
          if (indent >= baseIndent) {
            tailLines.push(stripIndent(currentLine, baseIndent));
            index += 1;
            continue;
          }

          break;
        }

        let itemHtml = '';
        const hasFirstText = !isBlank(firstText);

        if (tailLines.length === 0) {
          itemHtml = hasFirstText ? renderInline(firstText) : '';
        } else {
          let tailNeedsBlocks = false;
          for (let tailIndex = 0; tailIndex < tailLines.length; tailIndex += 1) {
            if (startsTailBlock(tailLines[tailIndex])) {
              tailNeedsBlocks = true;
              break;
            }
          }

          if (!tailNeedsBlocks) {
            const mergedText = hasFirstText ? `${firstText}\n${tailLines.join('\n')}` : tailLines.join('\n');
            itemHtml = renderInline(mergedText);
          } else {
            const tailHtml = renderLines(tailLines);
            if (hasFirstText) {
              itemHtml = renderInline(firstText);
              if (tailHtml) {
                if (tailHtml.startsWith('<ul>') || tailHtml.startsWith('<ol>') || tailHtml.startsWith('<blockquote>') || tailHtml.startsWith('<pre>')) {
                  itemHtml += tailHtml;
                } else {
                  itemHtml += `\n${tailHtml}`;
                }
              }
            } else {
              itemHtml = unwrapLeadingParagraph(tailHtml);
            }
          }
        }

        items.push(`<li>${itemHtml}</li>`);
      }

      blocks.push(`<${tagName}>\n${items.join('\n')}\n</${tagName}>`);
      continue;
    }

    if (countLeadingColumns(line) >= 4) {
      const codeLines = [];
      while (index < lines.length) {
        const currentLine = lines[index];
        if (isBlank(currentLine)) {
          codeLines.push('');
          index += 1;
          continue;
        }

        if (countLeadingColumns(currentLine) < 4) {
          break;
        }

        codeLines.push(stripIndent(currentLine, 4));
        index += 1;
      }

      blocks.push(`<pre><code>${escapeCodeText(codeLines.join('\n'))}\n</code></pre>`);
      continue;
    }

    const paragraphLines = [line];
    index += 1;

    while (index < lines.length && !isBlank(lines[index])) {
      if (startsParagraphInterrupt(lines[index])) {
        break;
      }
      paragraphLines.push(lines[index]);
      index += 1;
    }

    blocks.push(`<p>${renderInline(paragraphLines.join('\n'))}</p>`);
  }

  return blocks.join('\n');
}

export function renderMarkdown(value) {
  const normalized = normalizeNewlines(value);
  const lines = splitLines(normalized);

  let hasContent = false;
  for (let index = 0; index < lines.length; index += 1) {
    if (!isBlank(lines[index])) {
      hasContent = true;
      break;
    }
  }

  if (!hasContent) {
    return '';
  }

  return renderLines(lines);
}

