import { basename } from './text_utils.mjs';

export function getProgramName(argv) {
  return basename(argv[1] || 'test6.mjs') || 'test6.mjs';
}

export function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

export function formatHelp(programName) {
  return `${formatUsage(programName)}

Multiple markdown conversions

options:
  -h, --help  show this help message and exit
  --a A
  --b B
`;
}

function resolveLongOption(name) {
  if (name === 'a') {
    return 'a';
  }

  if (name === 'b') {
    return 'b';
  }

  if (name && 'help'.startsWith(name)) {
    return 'help';
  }

  return null;
}

function shouldRejectAsMissingValue(token) {
  return token.length > 1 && token[0] === '-';
}

export function parseArguments(argv) {
  const values = {
    a: undefined,
    b: undefined,
  };
  const unknown = [];
  const args = argv.slice(2);
  let stopOptionParsing = false;

  for (let index = 0; index < args.length; index += 1) {
    const token = args[index];

    if (stopOptionParsing) {
      unknown.push(token);
      continue;
    }

    if (token === '--') {
      stopOptionParsing = true;
      continue;
    }

    if (token === '-h') {
      return {
        kind: 'help',
      };
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const optionText = equalsIndex >= 0 ? token.slice(2, equalsIndex) : token.slice(2);
      const optionName = resolveLongOption(optionText);

      if (optionName === 'help') {
        return {
          kind: 'help',
        };
      }

      if (optionName === 'a' || optionName === 'b') {
        if (equalsIndex >= 0) {
          values[optionName] = token.slice(equalsIndex + 1);
          continue;
        }

        const nextToken = index + 1 < args.length ? args[index + 1] : undefined;
        if (nextToken === undefined || shouldRejectAsMissingValue(nextToken)) {
          return {
            kind: 'error',
            message: `argument --${optionName}: expected one argument`,
          };
        }

        values[optionName] = nextToken;
        index += 1;
        continue;
      }

      unknown.push(token);
      if (equalsIndex < 0 && index + 1 < args.length) {
        const nextToken = args[index + 1];
        if (nextToken !== '--' && !(nextToken.length > 0 && nextToken[0] === '-')) {
          unknown.push(nextToken);
          index += 1;
        }
      }
      continue;
    }

    unknown.push(token);
  }

  const missing = [];
  if (values.a === undefined) {
    missing.push('--a');
  }
  if (values.b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    return {
      kind: 'error',
      message: `the following arguments are required: ${missing.join(', ')}`,
    };
  }

  if (unknown.length > 0) {
    return {
      kind: 'error',
      message: `unrecognized arguments: ${unknown.join(' ')}`,
    };
  }

  return {
    kind: 'ok',
    values,
  };
}

