import { formatHelp, formatUsage, getProgramName, parseArguments } from './lib/cli.mjs';
import { renderMarkdown } from './lib/markdown.mjs';

export function main(argv = process.argv) {
  const programName = getProgramName(argv);
  const parsed = parseArguments(argv);

  if (parsed.kind === 'help') {
    process.stdout.write(formatHelp(programName));
    return 0;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(`${formatUsage(programName)}\n`);
    process.stderr.write(`${programName}: error: ${parsed.message}\n`);
    return 2;
  }

  console.log(renderMarkdown(parsed.values.a));
  console.log(renderMarkdown(parsed.values.b));
  return 0;
}

const exitCode = main();
if (exitCode !== 0) {
  process.exitCode = exitCode;
}

